function DetailPanel({task,patchTask}:{task:Task;patchTask:(id:string,patch:Partial<Task>)=>void}){return <div className="wv2-form"><h3>업무 상세</h3><label><span>업무명</span><input value={task.name} onChange={event=>patchTask(task.id,{name:event.target.value})}/></label><div className="three wv2-plan-fields"><label><span>계획 시작</span><input type="date" value={task.plannedStart||""} onChange={event=>patchTask(task.id,{plannedStart:event.target.value})}/></label><label><span>소요일</span><input type="number" min="1" value={Math.max(1,task.durationDays||1)} onChange={event=>patchTask(task.id,{durationDays:Math.max(1,Number(event.target.value)||1)})}/></label><label><span>계획 종료</span><input type="date" value={task.plannedEnd||""} onChange={event=>patchTask(task.id,{plannedEnd:event.target.value})}/></label></div><div className="two"><label><span>Role</span><input value={task.roleCode||""} placeholder="Role" readOnly/></label><label><span>담당자</span><input value={task.assigneeName||"미배정"} readOnly/></label></div><label><span>상태</span><input value={statusLabel(task.status)} readOnly/></label><section className="wv2-completion-card"><header><b>완료 기준</b><em>{task.completionActor==="PM"?"PM 승인":task.completionActor==="PL"?"PL 승인":"담당자 완료"}</em></header><p>{completionCriteriaLabel(task.completionCriteria)}</p>{task.deliverables.length>0&&<div>{task.deliverables.map(item=><span key={item.id||item.name}><FileText size={18}/>{item.name}{item.required!==false&&<b>필수</b>}</span>)}</div>}</section><section className="wv2-context-card"><b>연결 정보</b><div><span>산출물</span><strong>{task.deliverables.length}건</strong></div><div><span>이슈·협업</span><strong>{task.issueCount||0}건</strong></div></section></div>}
function ActualPanel({project,task,patchTask}:{project:Project|null;task:Task;patchTask:(id:string,patch:Partial<Task>)=>void}){const [actualDate,setActualDate]=useState(new Date().toISOString().slice(0,10));const [hours,setHours]=useState(0);const [progress,setProgress]=useState(task.progress);const [note,setNote]=useState("");const [completed,setCompleted]=useState(task.status==="completed"||task.status==="review");const [criteriaConfirmed,setCriteriaConfirmed]=useState(false);const [saving,setSaving]=useState(false);const [notice,setNotice]=useState("");useEffect(()=>{setProgress(task.progress);setCompleted(task.status==="completed"||task.status==="review");setCriteriaConfirmed(false)},[task.id,task.progress,task.status]);const request=async(action?:"approve"|"reject")=>{if(!project)return;setSaving(true);setNotice("");try{const response=await fetch(`/api/projects/${project.id}/actuals`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({taskId:task.id,action,actualDate,actualHours:hours,progress,workNote:note,completed:action?undefined:completed,completionConfirmed:criteriaConfirmed})});const result=await response.json();if(!response.ok)throw new Error(result.error||"실적을 저장하지 못했습니다.");patchTask(task.id,{progress:result.progress,status:result.status});setNotice(result.message||"실적을 저장했습니다.");setNote("");setCriteriaConfirmed(false)}catch(reason){setNotice(reason instanceof Error?reason.message:"실적을 저장하지 못했습니다.")}finally{setSaving(false)}};const required=task.deliverables.filter(item=>item.required!==false);return <div className="wv2-form"><h3>WBS 실적입력</h3><p>업무 화면을 벗어나지 않고 실적과 연결 자료를 함께 입력합니다.</p>{task.status==="review"&&<section className="wv2-review-card"><b>완료 승인 대기</b><p>{completionCriteriaLabel(task.completionCriteria)}</p><small>{task.completionActor==="PM"?"PM":"PL 또는 PM"}이 완료를 승인할 수 있습니다.</small><div><button disabled={saving} onClick={()=>request("reject")}>보완 요청</button><button className="primary" disabled={saving} onClick={()=>request("approve")}>완료 승인</button></div></section>}<div className="two"><label><span>실적일</span><input type="date" value={actualDate} onChange={event=>setActualDate(event.target.value)}/></label><label><span>실적공수</span><input type="number" min="0" step="0.5" value={hours} onChange={event=>setHours(Number(event.target.value))}/></label></div><label><span>진척률</span><div className="wv2-progress-input"><input type="range" min="0" max="100" value={progress} disabled={task.status==="review"} onChange={event=>setProgress(Number(event.target.value))}/><b>{progress}%</b></div></label><div className="wv2-quick-progress">{[25,50,75,100].map(value=><button key={value} disabled={task.status==="review"} onClick={()=>{setProgress(value);setCompleted(value===100)}}>{value}%</button>)}</div><label><span>오늘 작업 내용</span><textarea rows={7} value={note} onChange={event=>setNote(event.target.value)} placeholder={task.status==="review"?"승인 또는 보완 요청 사유를 입력하세요.":"진행 내용, 의사결정, 다음 작업을 기록하세요."}/></label>{task.status!=="review"&&<><label className="wv2-check"><input type="checkbox" checked={completed} onChange={event=>{setCompleted(event.target.checked);if(event.target.checked)setProgress(100)}}/> Task 완료 {task.completionActor&&task.completionActor!=="assignee"?"검토 요청":""}</label>{completed&&<section className="wv2-completion-check"><b>완료 전 확인</b><p>{completionCriteriaLabel(task.completionCriteria)}</p><small>필수 산출물 {required.length}건은 모두 파일 등록 상태여야 합니다.</small><label className="wv2-check"><input type="checkbox" checked={criteriaConfirmed} onChange={event=>setCriteriaConfirmed(event.target.checked)}/> 완료 조건을 확인했습니다.</label></section>}</>}{notice&&<p className="wv2-panel-notice">{notice}</p>}{task.status!=="review"&&<button className="wv2-panel-save" onClick={()=>request()} disabled={saving||Boolean(completed&&!criteriaConfirmed)}>{saving?"저장 중…":completed&&task.completionActor&&task.completionActor!=="assignee"?"실적 저장 · 완료 검토 요청":"실적 저장"}</button>}</div>}
